var showProject=function(){var project=state.project;el("project-title").textContent=project?project.name:"Choose a project";el("revision").textContent=project?"REV "+project.revision:"REV —";el("timeline-caption").textContent=project?"Select an asset, then run Gemini visual analysis.":"Select a project to begin.";el("upload").disabled=!project||!el("file-input").files.length;el("analyze").disabled=!state.selectedAsset;renderProjects();renderAssets()};
