el("upload").addEventListener("click",async function(){var file=el("file-input").files&&el("file-input").files[0];if(!file||!state.project)return;var button=el("upload");button.disabled=true;button.textContent="Importing…";try{var form=new FormData();form.append("file",file);var kind=file.type.indexOf("video/")===0?"video":file.type.indexOf("audio/")===0?"audio":"image";var response=await fetch("/api/v1/assets/uploads?projectId="+encodeURIComponent(state.project.projectId)+"&baseRevision="+encodeURIComponent(state.project.revision)+"&kind="+kind,{method:"POST",headers:{authorization:"Bearer "+state.token,accept:"application/json"},body:form});var body=await response.json().catch(function(){return {}});if(!response.ok||body.error)throw new Error((body.error&&body.error.message)||"Import failed");await loadProject(state.project.projectId);selectAsset(body.data.asset.id);notice("Media imported and stored in the project volume.")}catch(error){notice(error.message,true)}finally{button.textContent="Import to project";button.disabled=!state.project||!el("file-input").files.length}});
el("analyze").addEventListener("click",async function(){if(!state.project||!state.selectedAsset)return;var button=el("analyze");button.disabled=true;button.textContent="Starting Gemini…";try{var job=await api("POST","/api/v1/projects/"+encodeURIComponent(state.project.projectId)+"/assets/"+encodeURIComponent(state.selectedAsset.id)+"/analysis",{projectId:state.project.projectId,assetId:state.selectedAsset.id,analyzers:["google.vertex.gemini.video"],parameters:{},force:true});notice("Gemini job "+job.id.slice(0,8)+" started. The GCS object will be removed when it finishes.");await refresh(true)}catch(error){notice(error.message,true)}finally{button.textContent="Analyze selected asset";button.disabled=!state.selectedAsset}});
el("search-form").addEventListener("submit",async function(event){event.preventDefault();if(!state.project)return;var query=el("search-query").value.trim();var host=el("search-results");if(!query){host.innerHTML='<p class="empty">Type a description to search this project.</p>';return}try{var results=await api("POST","/api/v1/assets/search",{projectId:state.project.projectId,query:query,mode:"lexical",limit:20});host.innerHTML=results.length?results.map(function(result){return '<article class="result"><b>'+esc((result.labels||[]).slice(0,4).join(" · ")||"Visual segment")+'</b><p>'+esc(result.text||"No text summary")+'</p><small>'+esc(result.type||"analysis")+'</small></article>'}).join(""):'<p class="empty">No matching indexed footage yet.</p>'}catch(error){notice(error.message,true)}});
el("refresh").addEventListener("click",function(){refresh(true)});if(state.token){refresh(false).then(function(){if(state.projects.length)loadProject(state.projects[0].projectId)})}setInterval(function(){if(state.token)refresh(true)},5000);

/* The human editor uses exactly the transaction contract exposed to agents. */
state.operations=[];state.selectedItem=null;state.selectedTrackId=null;state.playhead=0;state.transportPlaying=false;
var uid=function(){return crypto.randomUUID()};
var time=function(seconds){return {value:Math.max(0,Math.round(Number(seconds||0)*1000)),rate:{numerator:1000,denominator:1}}};
var range=function(start,duration){return {start:time(start),duration:time(Math.max(.001,duration))}};
var seconds=function(value){return value&&value.rate?Number(value.value||0)*Number(value.rate.denominator||1)/Number(value.rate.numerator||1)/1000:0};
var sequence=function(){return state.project&&state.project.sequences[state.project.settings.defaultSequenceId]};
var operation=function(type,args,targetId){return {operationId:uid(),type:type,preconditions:[],provenance:{actorType:"human",actorId:"studio.editor"},...(targetId?{targetId:targetId}:{}),arguments:args}};
var activeTrack=function(){var seq=sequence();if(!seq)return null;return seq.tracks.find(function(track){return track.id===state.selectedTrackId})||seq.tracks.find(function(track){return state.selectedItem&&track.items.some(function(item){return item.id===state.selectedItem.id})})||seq.tracks.find(function(track){return track.kind==="video"})||seq.tracks[0]||null};
var selection=function(){var seq=sequence(),track=activeTrack();return seq&&track&&state.selectedItem?{sequence:seq,track:track,item:state.selectedItem}:null};
