var timelineEnd=function(track){return Math.max.apply(Math,[0].concat((track.items||[]).map(function(item){return seconds(item.timelineRange.start)+seconds(item.timelineRange.duration)})))};
var fillInspector=function(){var selected=selection(),item=selected&&selected.item,transform=item&&item.transform||{};el("selected-item-name").textContent=item?(item.type.toUpperCase()+" / "+item.name):"No timeline item selected";el("transform-x").value=transform.positionX||0;el("transform-y").value=transform.positionY||0;el("transform-scale").value=transform.scaleX===undefined?1:transform.scaleX;el("transform-rotation").value=transform.rotation||0;el("transform-opacity").value=transform.opacity===undefined?1:transform.opacity;el("audio-gain").value=item&&item.audio?item.audio.gainDb||0:0;el("audio-pan").value=item&&item.audio?item.audio.pan||0:0};
var renderTimeline=function(){var host=el("timeline"),seq=sequence();if(!seq){host.innerHTML='<div class="timeline-empty">Create or select a project to build the timeline.</div>';return}var total=Math.max(20,Math.max.apply(Math,[0].concat(seq.tracks.map(timelineEnd)))+2);host.innerHTML=seq.tracks.map(function(track){var controls='<div class="track-actions"><button data-track-lock="'+track.id+'">'+(track.locked?"UNLOCK":"LOCK")+'</button><button data-track-mute="'+track.id+'">'+(track.muted?"UNMUTE":"MUTE")+'</button></div>';var items=(track.items||[]).map(function(item){var start=seconds(item.timelineRange.start),duration=seconds(item.timelineRange.duration),selected=state.selectedItem&&item.id===state.selectedItem.id;return '<button class="timeline-item '+esc(item.type)+(selected?" active":"")+'" data-item="'+item.id+'" data-track="'+track.id+'" style="left:'+((start/total)*100)+'%;width:'+Math.max(4,(duration/total)*100)+'%"><b>'+esc(item.name)+'</b><small>'+item.type+' · '+duration.toFixed(1)+'s</small></button>'}).join("");return '<div class="track-row"><div class="track-label"><b>'+esc(track.name)+'</b><span>'+esc(track.kind)+' '+controls+'</span></div><div class="track-lane">'+items+'</div></div>'}).join("");host.querySelectorAll("[data-item]").forEach(function(button){button.addEventListener("click",function(){var track=seq.tracks.find(function(value){return value.id===button.dataset.track}),item=track&&track.items.find(function(value){return value.id===button.dataset.item});state.selectedTrackId=track&&track.id||null;state.selectedItem=item||null;renderTimeline();fillInspector()})});host.querySelectorAll("[data-track-lock]").forEach(function(button){button.addEventListener("click",function(){var track=seq.tracks.find(function(value){return value.id===button.dataset.track});transact([operation(track.locked?"track.unlock":"track.lock",{sequenceId:seq.id},track.id)]).catch(function(error){notice(error.message,true)})})});host.querySelectorAll("[data-track-mute]").forEach(function(button){button.addEventListener("click",function(){var track=seq.tracks.find(function(value){return value.id===button.dataset.track});transact([operation(track.muted?"track.unmute":"track.mute",{sequenceId:seq.id},track.id)]).catch(function(error){notice(error.message,true)})})});fillInspector()};
var originalRenderAssets=renderAssets;renderAssets=function(){originalRenderAssets();renderTimeline()};
var originalShowProject=showProject;showProject=function(){originalShowProject();renderTimeline()};
var originalLoadProject=loadProject;loadProject=async function(id){await originalLoadProject(id);var seq=sequence();if(seq&&!state.selectedTrackId)state.selectedTrackId=(seq.tracks.find(function(track){return track.kind==="video"})||seq.tracks[0]||{}).id||null;renderTimeline()};
var placeAsset=async function(){var seq=sequence(),track=activeTrack(),asset=state.selectedAsset;if(!seq||!track||!asset)throw new Error("Select a project, a timeline track, and an imported asset.");var duration=Number(el("clip-seconds").value)||10;if(asset.duration)duration=Math.max(.1,seconds(asset.duration));var start=timelineEnd(track),clip={id:uid(),type:"clip",name:asset.name,timelineRange:range(start,duration),enabled:true,locked:false,metadata:{},assetId:asset.id,sourceRange:range(0,duration),transform:{},timeMap:[],effects:[],audio:{},links:[],semanticMetadata:{}};await transact([operation("clip.append",{sequenceId:seq.id,trackId:track.id,clip:clip})]);state.selectedItem=clip;state.selectedTrackId=track.id};
var addTrack=async function(kind){var seq=sequence();if(!seq)throw new Error("Choose a project first.");var count=seq.tracks.filter(function(track){return track.kind===kind}).length+1,track={id:uid(),name:(kind==="video"?"V":"A")+count,kind:kind,order:Math.max.apply(Math,[0].concat(seq.tracks.map(function(item){return item.order||0})))+1,enabled:true,locked:false,muted:false,syncLocked:true,items:[],effects:[],metadata:{}};await transact([operation("track.add",{sequenceId:seq.id,track:track})]);state.selectedTrackId=track.id};
var addTitle=async function(){var seq=sequence(),track=activeTrack(),text=el("title-text").value.trim();if(!seq||!track)throw new Error("Choose a project and track first.");if(!text)throw new Error("Enter title text first.");var start=Number(el("playhead").value)||0,title={id:uid(),type:"title",name:text.slice(0,60),text:text,timelineRange:range(start,5),enabled:true,locked:false,metadata:{},style:{},transform:{},effects:[]};await transact([operation("title.add",{sequenceId:seq.id,trackId:track.id,title:title})]);el("title-text").value=""};
var addMarker=async function(){var seq=sequence(),name=el("marker-name").value.trim()||"Marker",at=Number(el("playhead").value)||0;if(!seq)throw new Error("Choose a project first.");await transact([operation("marker.add",{sequenceId:seq.id,marker:{id:uid(),name:name,range:range(at,.001),metadata:{},color:"orange"}})]);el("marker-name").value=""};
var addSplit=async function(){var value=selection(),at=Number(el("playhead").value);if(!value||value.item.type!=="clip")throw new Error("Select a clip to split.");var start=seconds(value.item.timelineRange.start),end=start+seconds(value.item.timelineRange.duration);if(!(at>start&&at<end))throw new Error("Place the playhead inside the selected clip before splitting.");await transact([operation("clip.split",{sequenceId:value.sequence.id,trackId:value.track.id,at:time(at),rightClipId:uid()},value.item.id)])};
var duplicate=async function(){var value=selection();if(!value||value.item.type!=="clip")throw new Error("Select a clip to duplicate.");await transact([operation("clip.duplicate",{sequenceId:value.sequence.id,trackId:value.track.id,newClipId:uid(),timelineStart:time(timelineEnd(value.track))},value.item.id)])};
