var loadOperation=async function(){var name=el("operation-select").value;if(!name)throw new Error("Choose an operation first.");var detail=await api("GET","/api/v1/operations/"+encodeURIComponent(name));el("operation-json").value=JSON.stringify([{operationId:"auto",type:name,preconditions:[],arguments:{}}],null,2);el("operation-schema").textContent=JSON.stringify({description:detail.description,requiredCapabilities:detail.requiredCapabilities,warnings:detail.expectedWarnings,inputSchema:detail.inputSchema},null,2)};
