var guard=function(fn){return function(){Promise.resolve(fn()).catch(function(error){notice(error.message||String(error),true)})}};
el("place-asset").addEventListener("click",guard(placeAsset));el("add-video-track").addEventListener("click",guard(function(){return addTrack("video")}));el("add-audio-track").addEventListener("click",guard(function(){return addTrack("audio")}));el("add-title").addEventListener("click",guard(addTitle));el("add-marker").addEventListener("click",guard(addMarker));el("split-clip").addEventListener("click",guard(addSplit));el("duplicate-clip").addEventListener("click",guard(duplicate));el("delete-clip").addEventListener("click",guard(deleteItem));el("apply-transform").addEventListener("click",guard(applyTransform));el("apply-audio").addEventListener("click",guard(applyAudio));el("undo").addEventListener("click",guard(async function(){await api("POST","/api/v1/projects/"+state.project.projectId+"/undo",{idempotencyKey:"studio-undo-"+uid()});await loadProject(state.project.projectId);notice("Undo committed.")}));el("redo").addEventListener("click",guard(async function(){await api("POST","/api/v1/projects/"+state.project.projectId+"/redo",{idempotencyKey:"studio-redo-"+uid()});await loadProject(state.project.projectId);notice("Redo committed.")}));el("preview-frame").addEventListener("click",guard(async function(){var seq=sequence(),job=await api("POST","/api/v1/previews",{projectId:state.project.projectId,sequenceId:seq.id,source:{type:"revision",revision:state.project.revision},kind:"frame",at:time(Number(el("playhead").value)||0)});notice("Frame preview job "+job.id.slice(0,8)+" queued.");await refresh(true)}));el("render-project").addEventListener("click",guard(async function(){var seq=sequence(),job=await api("POST","/api/v1/renders",{projectId:state.project.projectId,sequenceId:seq.id,outputName:"studio-render.mp4"});notice("Render job "+job.id.slice(0,8)+" queued.");await refresh(true)}));el("export-otio").addEventListener("click",guard(async function(){var data=await api("POST","/api/v1/exports/otio",{projectId:state.project.projectId});var url=URL.createObjectURL(new Blob([JSON.stringify(data.document||data,null,2)],{type:"application/json"})),link=document.createElement("a");link.href=url;link.download=(state.project.settings.name||"frameos")+".otio.json";link.click();URL.revokeObjectURL(url);notice("OTIO export downloaded.")}));el("operation-search").addEventListener("input",renderOperationOptions);el("load-operation").addEventListener("click",guard(loadOperation));el("run-operation").addEventListener("click",guard(runOperation));el("connect").addEventListener("click",function(){loadOperations().catch(function(error){notice(error.message,true)})});if(state.token)loadOperations().catch(function(){});
var loadSemanticPlan=async function(path,body,label){var plan=await api("POST",path,body);if(!Array.isArray(plan.operations)||!plan.operations.length)throw new Error(label+" returned no applicable edits.");el("operation-json").value=JSON.stringify(plan.operations,null,2);el("operation-mode").value="preview";el("operation-schema").textContent=JSON.stringify({planner:label,operations:plan.operations.length,warnings:plan.warnings||[],note:"Review the generated operations, then validate, preview, or commit them."},null,2);notice(label+" loaded into the workbench; review before applying.")};
el("plan-vertical").addEventListener("click",guard(function(){var seq=sequence();if(!seq)throw new Error("Choose a project first.");return loadSemanticPlan("/api/v1/semantic/make-vertical/plan",{projectId:state.project.projectId,baseRevision:state.project.revision,sequenceId:seq.id,outputWidth:1080,outputHeight:1920,fit:"cover",maximumOperations:200},"9:16 vertical plan")}));el("plan-silences").addEventListener("click",guard(function(){var seq=sequence(),track=activeTrack();if(!seq||!track)throw new Error("Choose a project and timeline track first.");return loadSemanticPlan("/api/v1/semantic/remove-silences/plan",{projectId:state.project.projectId,baseRevision:state.project.revision,trackIds:[track.id]},"Silence-removal plan")}));

/* Familiar NLE interactions: media-bin drop, draggable clips, trim handles, and a movable playhead. */
var clock=function(value){value=Math.max(0,Number(value)||0);return String(Math.floor(value/60)).padStart(2,"0")+":"+String(Math.floor(value%60)).padStart(2,"0")+"."+Math.floor((value%1)*10)};
var setPlayhead=function(value,seek){state.playhead=Math.max(0,Math.min(state.timelineDuration||Infinity,Number(value)||0));el("playhead").value=state.playhead.toFixed(1);el("transport-time").value=clock(state.playhead);var line=document.querySelector(".playhead-line");if(line)line.style.left=((state.playhead/(state.timelineDuration||30))*100)+"%";var video=el("video-preview");if(seek&&video&&!video.classList.contains("hidden")&&video.readyState>=1)video.currentTime=Math.min(Number.isFinite(video.duration)?video.duration:state.playhead,state.playhead)};
var appendAt=async function(asset,track,start){var seq=sequence();if(!seq||!asset||!track)throw new Error("Choose media and a target track first.");var duration=Number(el("clip-seconds").value)||10;if(asset.duration)duration=Math.max(.1,seconds(asset.duration));var clip={id:uid(),type:"clip",name:asset.name,timelineRange:range(start,duration),enabled:true,locked:false,metadata:{},assetId:asset.id,sourceRange:range(0,duration),transform:{},timeMap:[],effects:[],audio:{},links:[],semanticMetadata:{}};await transact([operation("clip.append",{sequenceId:seq.id,trackId:track.id,clip:clip})]);state.selectedItem=clip;state.selectedTrackId=track.id};
var previousAssets=renderAssets;renderAssets=function(){previousAssets();document.querySelectorAll("[data-asset]").forEach(function(button){button.draggable=true;button.title="Drag this media to a timeline track";button.addEventListener("dragstart",function(event){state.dragAsset=button.dataset.asset;event.dataTransfer.effectAllowed="copy"})})};
renderTimeline=function(){var host=el("timeline"),seq=sequence();if(!seq){host.innerHTML='<div class="timeline-empty">Create or select a project to build the timeline.</div>';return}var total=Math.max(30,Math.ceil(Math.max.apply(Math,[0].concat(seq.tracks.map(timelineEnd)))+5));state.timelineDuration=total;var ticks=[];for(var tick=0;tick<=total;tick+=5)ticks.push('<span style="left:'+((tick/total)*100)+'%">'+clock(tick)+'</span>');host.innerHTML='<div class="time-ruler">'+ticks.join("")+'</div>'+seq.tracks.map(function(track){var controls='<div class="track-actions"><button data-track-lock="'+track.id+'">'+(track.locked?"UNLOCK":"LOCK")+'</button><button data-track-mute="'+track.id+'">'+(track.muted?"UNMUTE":"MUTE")+'</button></div>';var items=(track.items||[]).map(function(item){var start=seconds(item.timelineRange.start),duration=seconds(item.timelineRange.duration),selected=state.selectedItem&&item.id===state.selectedItem.id;return '<button class="timeline-item '+esc(item.type)+(selected?" active":"")+'" data-item="'+item.id+'" data-track="'+track.id+'" style="left:'+((start/total)*100)+'%;width:'+Math.max(4,(duration/total)*100)+'%"><b>'+esc(item.name)+'</b><small>'+item.type+' · '+duration.toFixed(1)+'s</small>'+(item.type==="clip"?'<i class="trim-handle" title="Drag to trim clip end"></i>':"")+'</button>'}).join("");return '<div class="track-row"><div class="track-label"><b>'+esc(track.name)+'</b><span>'+esc(track.kind)+' '+controls+'</span></div><div class="track-lane" data-lane="'+track.id+'">'+items+'</div></div>'}).join("")+'<i class="playhead-line" style="left:'+((state.playhead||0)/total*100)+'%"></i>';
host.querySelectorAll("[data-item]").forEach(function(button){button.addEventListener("click",function(event){if(state.timelinePointer)return;var track=seq.tracks.find(function(value){return value.id===button.dataset.track}),item=track&&track.items.find(function(value){return value.id===button.dataset.item});state.selectedTrackId=track&&track.id||null;state.selectedItem=item||null;fillInspector();renderTimeline()});button.addEventListener("pointerdown",function(event){var track=seq.tracks.find(function(value){return value.id===button.dataset.track}),item=track&&track.items.find(function(value){return value.id===button.dataset.item});if(!track||!item)return;state.selectedTrackId=track.id;state.selectedItem=item;if(item.type!=="clip"){fillInspector();return}event.preventDefault();state.timelinePointer={mode:event.target.classList.contains("trim-handle")?"trim":"move",button:button,track:track,item:item,startX:event.clientX,initialStart:seconds(item.timelineRange.start),initialDuration:seconds(item.timelineRange.duration),total:total};button.setPointerCapture&&button.setPointerCapture(event.pointerId);fillInspector()})});
host.querySelectorAll("[data-lane]").forEach(function(lane){lane.addEventListener("dragover",function(event){event.preventDefault();lane.style.outline="1px solid var(--acid)"});lane.addEventListener("dragleave",function(){lane.style.outline=""});lane.addEventListener("drop",function(event){event.preventDefault();lane.style.outline="";var asset=state.assets.find(function(value){return value.id===state.dragAsset}),track=seq.tracks.find(function(value){return value.id===lane.dataset.lane}),rect=lane.getBoundingClientRect(),start=Math.max(0,(event.clientX-rect.left)/rect.width*total);appendAt(asset,track,start).catch(function(error){notice(error.message,true)})})});
host.querySelectorAll("[data-track-lock]").forEach(function(button){button.addEventListener("click",function(){var track=seq.tracks.find(function(value){return value.id===button.dataset.track});transact([operation(track.locked?"track.unlock":"track.lock",{sequenceId:seq.id},track.id)]).catch(function(error){notice(error.message,true)})})});host.querySelectorAll("[data-track-mute]").forEach(function(button){button.addEventListener("click",function(){var track=seq.tracks.find(function(value){return value.id===button.dataset.track});transact([operation(track.muted?"track.unmute":"track.mute",{sequenceId:seq.id},track.id)]).catch(function(error){notice(error.message,true)})})});host.addEventListener("pointerdown",function(event){if(event.target.closest(".timeline-item"))return;var rect=host.getBoundingClientRect();setPlayhead((event.clientX-rect.left)/rect.width*total,true);state.playheadPointer=true});fillInspector()};
document.addEventListener("pointermove",function(event){var action=state.timelinePointer;if(action){var lane=action.button.closest(".track-lane"),rect=lane.getBoundingClientRect(),delta=(event.clientX-action.startX)/rect.width*action.total;if(action.mode==="move"){var next=Math.max(0,action.initialStart+delta);action.button.style.left=(next/action.total*100)+"%"}else{var duration=Math.max(.1,action.initialDuration+delta);action.button.style.width=Math.max(4,duration/action.total*100)+"%"}}else if(state.playheadPointer){var host=el("timeline"),rect=host.getBoundingClientRect();setPlayhead((event.clientX-rect.left)/rect.width*(state.timelineDuration||30),true)}});
document.addEventListener("pointerup",function(event){if(state.playheadPointer){state.playheadPointer=false;return}var action=state.timelinePointer;if(!action)return;state.timelinePointer=null;var lane=document.elementFromPoint(event.clientX,event.clientY);lane=lane&&lane.closest(".track-lane");var rect=(lane||action.button.closest(".track-lane")).getBoundingClientRect(),delta=(event.clientX-action.startX)/rect.width*action.total;if(action.mode==="move"){var destination=sequence().tracks.find(function(track){return track.id===((lane&&lane.dataset.lane)||action.track.id)}),start=Math.max(0,action.initialStart+delta);transact([operation("clip.move",{sequenceId:sequence().id,fromTrackId:action.track.id,toTrackId:destination.id,timelineStart:time(start)},action.item.id)]).catch(function(error){notice(error.message,true);renderTimeline()})}else{var source=Object.assign({},action.item.sourceRange,{duration:time(Math.max(.1,seconds(action.item.sourceRange.duration)+delta))});transact([operation("clip.trim",{sequenceId:sequence().id,trackId:action.track.id,sourceRange:source},action.item.id)]).catch(function(error){notice(error.message,true);renderTimeline()})}});
el("playhead").addEventListener("change",function(){setPlayhead(el("playhead").value,true)});["transport-start","transport-back","transport-forward","transport-end"].forEach(function(id){el(id).addEventListener("click",function(){var change=id==="transport-start"?0:id==="transport-end"?state.timelineDuration:id==="transport-back"?(state.playhead||0)-1:(state.playhead||0)+1;setPlayhead(change,true)})});el("transport-play").addEventListener("click",function(){var video=el("video-preview");if(video.classList.contains("hidden")){notice("Choose a local video file to use the source monitor.",true);return}if(video.paused){video.play();state.transportPlaying=true;this.textContent="Pause"}else{video.pause();state.transportPlaying=false;this.textContent="Play"}});el("video-preview").addEventListener("loadedmetadata",function(){setPlayhead(state.playhead,true)});el("video-preview").addEventListener("timeupdate",function(){if(state.transportPlaying&&!this.paused)setPlayhead(this.currentTime,false)});el("video-preview").addEventListener("pause",function(){state.transportPlaying=false;el("transport-play").textContent="Play"});

var previewImportedAsset=async function(asset){if(!asset||asset.kind!=="video"||state.assetPreviewId===asset.id)return;if(state.previewLoadingId===asset.id)return;state.previewLoadingId=asset.id;try{var response=await fetch("/api/v1/projects/"+encodeURIComponent(state.project.projectId)+"/assets/"+encodeURIComponent(asset.id)+"/content",{headers:{authorization:"Bearer "+state.token}});if(!response.ok)throw new Error("Could not load the selected video ("+response.status+").");var blob=await response.blob(),url=URL.createObjectURL(blob),video=el("video-preview"),placeholder=document.querySelector(".preview-placeholder");if(state.previewUrl)URL.revokeObjectURL(state.previewUrl);state.previewUrl=url;state.assetPreviewId=asset.id;video.src=url;video.classList.remove("hidden");placeholder.classList.add("hidden");el("selected-file").textContent=asset.name+" · loaded from project";video.load()}catch(error){notice(error.message||String(error),true)}finally{state.previewLoadingId=null}};
var selectAssetForPreview=selectAsset;selectAsset=function(id){selectAssetForPreview(id);previewImportedAsset(state.selectedAsset)};
